-- PREPARED ONLY: R-01..R-12, Web/Desktop planning evidence, version 2026-10-16.2.
-- Not applied. Existing care_tours, Android, visit execution and logbook writers stay native.
-- Dependencies: native care/HR/logbook tables and care_personnel_private roots/events.
-- Gates: real PostgreSQL/PostgREST/RLS/SDK, source locks/deadlocks, two-session races,
-- native execution/writer compatibility and qualified care/privacy/operations acceptance.
begin;
create schema if not exists care_tour_planning_private;
revoke all on schema care_tour_planning_private from public,anon,authenticated;
create table if not exists care_tour_planning_private.roots(
 tenant_id uuid not null,plan_id uuid not null,head_id uuid,updated_at timestamptz not null default clock_timestamp(),primary key(tenant_id,plan_id));
create table if not exists care_tour_planning_private.events(
 id uuid primary key,tenant_id uuid not null,plan_id uuid not null,sequence bigint not null,previous_id uuid,request_id uuid not null,
 actor_id uuid not null,actor_name text not null,occurred_at timestamptz not null,recorded_at timestamptz not null default clock_timestamp(),
 kind text not null,command jsonb not null,unique(tenant_id,plan_id,sequence),unique(tenant_id,request_id));
alter table care_tour_planning_private.roots enable row level security;
alter table care_tour_planning_private.events enable row level security;
revoke all on all tables in schema care_tour_planning_private from public,anon,authenticated;
create or replace function care_tour_planning_private.immutable()returns trigger language plpgsql security definer set search_path='' as $$
begin raise exception using errcode='P0P01',message='Planungsoriginale bleiben unveränderlich.';end$$;
drop trigger if exists tour_planning_roots_delete on care_tour_planning_private.roots;
create trigger tour_planning_roots_delete before delete on care_tour_planning_private.roots for each row execute function care_tour_planning_private.immutable();
drop trigger if exists tour_planning_events_immutable on care_tour_planning_private.events;
create trigger tour_planning_events_immutable before update or delete on care_tour_planning_private.events for each row execute function care_tour_planning_private.immutable();

create or replace function care_tour_planning_private.profile_has(t uuid,a uuid,keys text[])returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'
 and not exists(select 1 from unnest(keys) k where not case when exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key)
 then exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key and z.permission_key=k)
 else exists(select 1 from public.role_permissions z where z.role_id=r.id and z.permission_key=k)end))$$;
create or replace function care_tour_planning_private.identity(t uuid,a uuid,keys text[],writing boolean)returns text language plpgsql security definer set search_path='' as $$
declare sid uuid;n text;k text;begin
 if auth.uid() is null or auth.uid() is distinct from a or public.resolve_current_profile_id() is distinct from a or public.current_tenant_id() is distinct from t
 or coalesce((auth.jwt()->>'exp')::bigint,0)<=extract(epoch from clock_timestamp())then raise exception using errcode='42501',message='Aktuelles eigenes Konto fehlt.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;
 perform 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid() and(s.not_after is null or s.not_after>clock_timestamp())for share;
 if not found then raise exception using errcode='42501',message='Aktuelle native Sitzung fehlt.';end if;
 if writing then lock table public.roles,public.role_permissions,public.role_permission_sets in share mode;end if;
 select coalesce(nullif(btrim(p.display_name),''),'Name nicht bestätigt')into n from public.profiles p join public.roles r on r.id=p.role_id
 where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and(p.auth_user_id is null or p.auth_user_id=auth.uid())for share of p,r;
 if n is null or not care_tour_planning_private.profile_has(t,a,keys)then raise exception using errcode='42501',message='Aktuelle Planungs- oder Quellrechte fehlen.';end if;
 foreach k in array keys loop if public.has_permission(k)is not true then raise exception using errcode='42501',message='Nativer Rechtezugang fehlt.';end if;end loop;
 return n;
end$$;
create or replace function care_tour_planning_private.actor(p_tenant uuid,p_actor uuid,p_write boolean default false)returns text language sql security definer set search_path='' as $$
 select care_tour_planning_private.identity(p_tenant,p_actor,array['pflege.plans.view','office.employees.view','office.employees.view_sensitive','office.clients.view','office.clients.view_sensitive','office.documents.view','pflege.documentation.view']||case when p_write then array['pflege.plans.manage']else array[]::text[]end,p_write)$$;
create or replace function care_tour_planning_private.recipient_actor(t uuid,a uuid,writing boolean default false)returns text language plpgsql security definer set search_path='' as $$
declare n text;begin
 n:=care_tour_planning_private.identity(t,a,array['pflege.plans.view'],writing);
 perform 1 from public.employees e where e.tenant_id=t and e.profile_id=a and e.status in('active','aktiv')for share;
 if not found then raise exception using errcode='42501',message='Aktuelle eigene Personalverknüpfung fehlt.';end if;return n;
end$$;
create or replace function care_tour_planning_private.plan_original(p_tenant uuid,p_plan uuid)returns jsonb language sql security definer set search_path='' as $$
 select to_jsonb(t)from public.care_tours t where t.tenant_id=p_tenant and t.id=p_plan$$;
create or replace function care_tour_planning_private.event_json(e care_tour_planning_private.events)returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'planId',e.plan_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)$$;
create or replace function care_tour_planning_private.live_events(t uuid,p uuid)returns setof care_tour_planning_private.events language sql stable set search_path='' as $$
 select e.*from care_tour_planning_private.events e where e.tenant_id=t and e.plan_id=p and e.kind<>'correct'and not exists(select 1 from care_tour_planning_private.events z where z.tenant_id=t and z.plan_id=p and z.kind='correct'and z.command#>>'{payload,targetId}'=e.id::text)$$;
create or replace function care_tour_planning_private.history(p_tenant uuid,p_plan uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare e care_tour_planning_private.events%rowtype;head uuid;prev uuid;n bigint:=0;rows jsonb:='[]';last_recorded timestamptz;begin
 select r.head_id into head from care_tour_planning_private.roots r where r.tenant_id=p_tenant and r.plan_id=p_plan;
 for e in select*from care_tour_planning_private.events z where z.tenant_id=p_tenant and z.plan_id=p_plan order by z.sequence loop
 if e.sequence<>n+1 or e.previous_id is distinct from prev or e.command->>'eventId' is distinct from e.id::text or e.command->>'actorId' is distinct from e.actor_id::text
 or e.command->>'tenantId' is distinct from p_tenant::text or e.command->>'planId' is distinct from p_plan::text or e.command->>'kind' is distinct from e.kind or(e.command->>'expectedHeadId')is distinct from prev::text or e.occurred_at>e.recorded_at or e.recorded_at<last_recorded
 then raise exception using errcode='23514',message='Vollständiger Originalverlauf ist widersprüchlich.';end if;
 rows:=rows||jsonb_build_array(care_tour_planning_private.event_json(e));prev:=e.id;n:=n+1;last_recorded:=e.recorded_at;
 end loop;
 if head is distinct from prev then raise exception using errcode='23514',message='Der Originalkopf ist nicht vollständig.';end if;
 return jsonb_build_object('version','2026-10-16.2','tenantId',p_tenant,'planId',p_plan,'count',n,'headId',head,'events',rows);
end$$;

create or replace function care_tour_planning_private.personnel_original(t uuid,eid uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare h jsonb;q jsonb;d jsonb;begin
 if to_regclass('care_personnel_private.events')is null or to_regclass('care_personnel_private.roots')is null then raise exception using errcode='P0P01',message='Der getrennte Personalentscheidungsbestand ist nicht verfügbar.';end if;
 select jsonb_build_object('version','2026-10-16.1','tenantId',t,'employeeId',eid,'count',count(e.id),'headId',r.head_id,'events',coalesce(jsonb_agg(jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'employeeId',e.employee_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)order by e.sequence)filter(where e.id is not null),'[]'::jsonb))into h
 from care_personnel_private.roots r left join care_personnel_private.events e on e.tenant_id=r.tenant_id and e.employee_id=r.employee_id where r.tenant_id=t and r.employee_id=eid group by r.head_id;
 h:=coalesce(h,jsonb_build_object('version','2026-10-16.1','tenantId',t,'employeeId',eid,'count',0,'headId',null,'events','[]'::jsonb));
 select coalesce(jsonb_agg(jsonb_build_object('kind','qualification','id',x.id,'snapshot',to_jsonb(x))order by x.id),'[]')into q from public.employee_qualifications x where x.tenant_id=t and x.employee_id=eid;
 select coalesce(jsonb_agg(jsonb_build_object('kind','document','id',x.id,'snapshot',to_jsonb(x))order by x.id),'[]')into d from public.employee_documents x where x.tenant_id=t and x.employee_id=eid;
 return jsonb_build_object('kind','personnel','id',eid,'snapshot',jsonb_build_object('id',eid,'tenant_id',t,'history',h,'qualifications',q,'documents',d));
end$$;
create or replace function care_tour_planning_private.sources(p_tenant uuid,p_plan uuid)returns jsonb language sql security definer set search_path='' as $$
 with tour as(select*from public.care_tours where tenant_id=p_tenant and id=p_plan),stops as(select s.*from public.care_tour_stops s join tour t on t.id=s.tour_id and t.tenant_id=s.tenant_id),clients as(select distinct client_id from stops where client_id is not null),staff as(select e.*from public.employees e where e.tenant_id=p_tenant and e.status in('active','aktiv')),s as(
 select 'tour'::text kind,t.id,to_jsonb(t)snapshot from tour t
 union all select 'stop',x.id,to_jsonb(x)from stops x
 union all select 'shift',x.id,to_jsonb(x)from public.care_staff_shifts x where x.tenant_id=p_tenant and x.employee_id in(select id from staff)and x.shift_date in(select tour_date from tour)
 union all select 'availability',x.id,to_jsonb(x)from public.employee_availability x where x.tenant_id=p_tenant and x.employee_id in(select id from staff)
 union all select 'absence',x.id,to_jsonb(x)from public.employee_absences x where x.tenant_id=p_tenant and x.employee_id in(select id from staff)
 union all select 'qualification',x.id,to_jsonb(x)from public.employee_qualifications x where x.tenant_id=p_tenant and x.employee_id in(select id from staff)
 union all select 'work_rule',x.id,to_jsonb(x)from public.care_staff_shifts x where x.tenant_id=p_tenant and x.employee_id in(select id from staff)and x.shift_date in(select tour_date from tour)
 union all select 'preference',x.id,to_jsonb(x)from public.client_preferences x where x.tenant_id=p_tenant and x.client_id in(select client_id from clients)
 union all select 'admission',x.id,to_jsonb(x)from public.care_admissions x where x.tenant_id=p_tenant and x.client_id in(select client_id from clients)
 union all select 'care_plan',x.id,to_jsonb(x)from public.care_plans x where x.tenant_id=p_tenant and x.client_id in(select client_id from clients)
 union all select 'series',x.id,to_jsonb(x)from public.care_plan_items x join public.care_plans p on p.id=x.care_plan_id and p.tenant_id=x.tenant_id where x.tenant_id=p_tenant and p.client_id in(select client_id from clients)
 union all select 'vehicle',x.id,to_jsonb(x)from public.employee_logbook_vehicles x where x.tenant_id=p_tenant
 union all select 'maintenance',x.id,to_jsonb(x)from public.employee_logbook_vehicles x where x.tenant_id=p_tenant
 union all select 'trip',x.id,to_jsonb(x)from public.employee_logbook_trips x where x.tenant_id=p_tenant
 union all select 'personnel',x.id,care_tour_planning_private.personnel_original(p_tenant,x.id)->'snapshot'from staff x
 union all select 'resource',e.id,to_jsonb(e)||jsonb_build_object('tour_date',t.tour_date)from care_tour_planning_private.roots r join public.care_tours t on t.id=r.plan_id and t.tenant_id=r.tenant_id
 cross join lateral care_tour_planning_private.live_events(r.tenant_id,r.plan_id)e where r.tenant_id=p_tenant and r.plan_id<>p_plan and(
 e.kind='assignment'and e.sequence=(select max(z.sequence)from care_tour_planning_private.live_events(r.tenant_id,r.plan_id)z where z.kind='assignment')
 or e.kind='replan'and e.sequence>coalesce((select max(z.sequence)from care_tour_planning_private.live_events(r.tenant_id,r.plan_id)z where z.kind='assignment'),0)
 or e.kind='trip_start'and not exists(select 1 from care_tour_planning_private.live_events(r.tenant_id,r.plan_id)z where z.kind='trip_finish'and z.command#>>'{payload,tripStartEventId}'=e.id::text))
 )select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'snapshot',snapshot)order by kind,id),'[]'::jsonb)from s$$;
create or replace function care_tour_planning_private.people(p_tenant uuid)returns jsonb language sql security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'profileId',case when p.is_active and p.status='active'then e.profile_id end,'tenantId',e.tenant_id,'name',concat_ws(' ',e.first_name,e.last_name),'roleKey',coalesce(e.role_title,'employee'),'active',true,'updatedAt',to_char(e.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))order by e.last_name,e.first_name,e.id),'[]'::jsonb)
 from public.employees e left join public.profiles p on p.id=e.profile_id and p.tenant_id=e.tenant_id where e.tenant_id=p_tenant and e.status in('active','aktiv')$$;
create or replace function care_tour_planning_private.assert_source(p_tenant uuid,p_plan uuid,p_source jsonb)returns void language plpgsql security definer set search_path='' as $$
begin if jsonb_typeof(p_source)is distinct from 'object'or p_source is distinct from(select x from jsonb_array_elements(care_tour_planning_private.sources(p_tenant,p_plan))x where x->>'kind'=p_source->>'kind'and x->>'id'=p_source->>'id')then raise exception using errcode='40001',message='Vollständiges Original geändert oder unzugänglich.';end if;end$$;
create or replace function care_tour_planning_private.assert_person(p_tenant uuid,p_person jsonb)returns void language plpgsql security definer set search_path='' as $$
begin if p_person is distinct from(select x from jsonb_array_elements(care_tour_planning_private.people(p_tenant))x where x->>'id'=p_person->>'id')then raise exception using errcode='40001',message='Aktive beteiligte Person geändert.';end if;end$$;

create or replace function care_tour_planning_private.payload_spec(k text)returns jsonb language sql immutable set search_path='' as $$select $spec${"plan_version":{"keys":["tour","versionLabel","validFrom","validUntil","decision"],"fields":[{"key":"tour","label":"Aktuelle Tourfassung","type":"source","sourceKinds":["tour"]},{"key":"versionLabel","label":"Bezeichnung der neuen Planfassung","type":"text","optional":false},{"key":"validFrom","label":"Gültig ab","type":"date","optional":false},{"key":"validUntil","label":"Gültig bis","type":"date","optional":false},{"key":"decision","label":"Verantwortliche Planentscheidung","type":"text","optional":false}]},"rule_review":{"keys":["rule","shift","startedAt","endedAt","breakMinutes","result","exceptionReason"],"fields":[{"key":"rule","label":"Schichtvorgaben zur Prüfung","type":"source","sourceKinds":["work_rule"]},{"key":"shift","label":"Geprüfte Schicht","type":"source","sourceKinds":["shift"]},{"key":"startedAt","label":"Geplanter Beginn","type":"time","optional":false},{"key":"endedAt","label":"Geplantes Ende","type":"time","optional":false},{"key":"breakMinutes","label":"Pause in Minuten","type":"number","optional":false},{"key":"result","label":"Prüfergebnis","type":"choice","options":[{"key":"compliant","label":"Regelkonform geprüft"},{"key":"exception_required","label":"Ausnahme muss geklärt werden"},{"key":"rejected","label":"Zurückgewiesen"}]},{"key":"exceptionReason","label":"Geprüfte Regelgrundlage und gegebenenfalls offene Ausnahme","type":"text","optional":false}]},"visit_binding":{"keys":["tour","stop","admission","carePlan","frequency","serviceType","windowStart","windowEnd","continuity","decision"],"fields":[{"key":"tour","label":"Tourfassung","type":"source","sourceKinds":["tour"]},{"key":"stop","label":"Konkreter Besuch","type":"source","sourceKinds":["stop"]},{"key":"admission","label":"Aktive Aufnahme","type":"source","sourceKinds":["admission"]},{"key":"carePlan","label":"Geltender Pflege- oder Leistungsplan","type":"source","sourceKinds":["care_plan"]},{"key":"frequency","label":"Bedarf und Frequenz","type":"text","optional":false},{"key":"serviceType","label":"Konkrete Leistungsart","type":"text","optional":false},{"key":"windowStart","label":"Zeitfenster Beginn","type":"time","optional":false},{"key":"windowEnd","label":"Zeitfenster Ende","type":"time","optional":false},{"key":"continuity","label":"Versorgungsstand","type":"choice","options":[{"key":"active","label":"Versorgung aktiv"},{"key":"interrupted","label":"Unterbrochen"},{"key":"ended","label":"Beendet"}]},{"key":"decision","label":"Planungsentscheidung","type":"choice","options":[{"key":"planned","label":"Einplanen"},{"key":"blocked","label":"Gesperrt lassen"}]}]},"assignment":{"keys":["tour","shift","primary","primaryQualification","secondary","secondaryQualification","vehicle","maintenance","capacityMinutes","travelMinutes","accessSummary","decision","planVersionEventId","primaryPersonnel","secondaryPersonnel","startedAt","endedAt","activity","maintenanceEventId"],"fields":[{"key":"planVersionEventId","label":"Aktuelle geprüfte Planfassung","type":"event","eventKinds":["plan_version"],"optional":false},{"key":"tour","label":"Tourfassung","type":"source","sourceKinds":["tour"]},{"key":"primary","label":"Erste Person","type":"person","optional":false},{"key":"primaryPersonnel","label":"Aktueller Personalentscheidungsbestand der ersten Person","type":"source","sourceKinds":["personnel"]},{"key":"primaryQualification","label":"Genau geprüfte Qualifikation der ersten Person","type":"source","sourceKinds":["qualification"]},{"key":"shift","label":"Schicht der ersten Person","type":"source","sourceKinds":["shift"]},{"key":"secondary","label":"Zweite Person bei Doppelbesetzung","type":"person","optional":true},{"key":"secondaryPersonnel","label":"Personalentscheidungsbestand der zweiten Person","type":"source","sourceKinds":["personnel"],"optional":true},{"key":"secondaryQualification","label":"Eigene Qualifikation der zweiten Person","type":"source","sourceKinds":["qualification"],"optional":true},{"key":"activity","label":"Konkrete Tätigkeit wie in der Personalprüfung","type":"text","optional":false},{"key":"startedAt","label":"Zuordnung ab","type":"time","optional":false},{"key":"endedAt","label":"Zuordnung bis","type":"time","optional":false},{"key":"vehicle","label":"Fahrzeug","type":"source","sourceKinds":["vehicle"],"optional":true},{"key":"maintenanceEventId","label":"Ausdrückliche Fahrzeugfreigabe","type":"event","eventKinds":["maintenance"],"optional":true},{"key":"capacityMinutes","label":"Geprüfte Kapazität in Minuten","type":"number","optional":false},{"key":"travelMinutes","label":"Geplante Fahrtzeit in Minuten","type":"number","optional":false},{"key":"accessSummary","label":"Zugangsvoraussetzungen ohne Zugangscodes","type":"text","optional":false},{"key":"decision","label":"Zuordnungsentscheidung","type":"text","optional":false}]},"preference_exception":{"keys":["preference","stop","outcome","priority","reason"],"fields":[{"key":"stop","label":"Konkreter Besuch","type":"source","sourceKinds":["stop"]},{"key":"preference","label":"Zugehörige Vereinbarung oder Präferenz","type":"source","sourceKinds":["preference"]},{"key":"outcome","label":"Ergebnis","type":"choice","options":[{"key":"honored","label":"Berücksichtigt"},{"key":"deviation","label":"Begründete Abweichung"}]},{"key":"priority","label":"Vereinbarte Priorität","type":"choice","options":[{"key":"required","label":"Verbindlich"},{"key":"high","label":"Hohe Priorität"},{"key":"normal","label":"Normale Priorität"}]},{"key":"reason","label":"Begründung der Entscheidung","type":"text","optional":false}]},"replan":{"keys":["tour","stop","cause","previousAssignmentEventId","replacement","replacementQualification","notification","decision","replacementPersonnel","startedAt","endedAt","activity"],"fields":[{"key":"tour","label":"Tourfassung","type":"source","sourceKinds":["tour"]},{"key":"stop","label":"Noch nicht begonnener Besuch","type":"source","sourceKinds":["stop"]},{"key":"previousAssignmentEventId","label":"Aktuelle betroffene Zuordnung","type":"event","eventKinds":["assignment"],"optional":false},{"key":"cause","label":"Ausfall oder Abwesenheit der bisher zugeordneten Person","type":"source","sourceKinds":["absence"]},{"key":"replacement","label":"Geprüfte Ersatzperson","type":"person","optional":false},{"key":"replacementPersonnel","label":"Aktuelle Personalentscheidungen der Ersatzperson","type":"source","sourceKinds":["personnel"]},{"key":"replacementQualification","label":"Passende Qualifikation der Ersatzperson","type":"source","sourceKinds":["qualification"]},{"key":"activity","label":"Dieselbe konkrete Tätigkeit","type":"text","optional":false},{"key":"startedAt","label":"Vertretung ab","type":"time","optional":false},{"key":"endedAt","label":"Vertretung bis","type":"time","optional":false},{"key":"notification","label":"Dokumentierte Benachrichtigung und offene Rückmeldungen","type":"text","optional":false},{"key":"decision","label":"Umplanungsentscheidung","type":"text","optional":false}]},"series_exception":{"keys":["series","occurrenceId","originalDate","newDate","holidayCalendarVersion","action","reason","occurrence","carePlan"],"fields":[{"key":"series","label":"Versionierte Serienregel","type":"source","sourceKinds":["series"]},{"key":"occurrence","label":"Ausdrücklich zugeordneter Einzelbesuch","type":"source","sourceKinds":["stop"]},{"key":"carePlan","label":"Pflegeplan desselben Pflegefalls","type":"source","sourceKinds":["care_plan"]},{"key":"originalDate","label":"Ursprüngliches Datum","type":"date","optional":false},{"key":"newDate","label":"Neues Datum nur bei Verschiebung","type":"date","optional":true},{"key":"holidayCalendarVersion","label":"Tatsächlich geprüfte Feiertagskalenderfassung","type":"text","optional":false},{"key":"action","label":"Einzelentscheidung","type":"choice","options":[{"key":"keep","label":"Beibehalten"},{"key":"reschedule","label":"Einzeltermin verschieben"},{"key":"cancel","label":"Einzeltermin absagen"}]},{"key":"reason","label":"Ausnahmegrund","type":"text","optional":false}]},"publish":{"keys":["tour","planVersionEventId","versionLabel","validFrom","validUntil","recipients","decision","packet"],"fields":[{"key":"tour","label":"Freizugebende Tourfassung","type":"source","sourceKinds":["tour"]},{"key":"planVersionEventId","label":"Aktuelle unveränderliche Planfassung","type":"event","eventKinds":["plan_version"],"optional":false},{"key":"versionLabel","label":"Dieselbe Planbezeichnung","type":"text","optional":false},{"key":"validFrom","label":"Gültig ab","type":"date","optional":false},{"key":"validUntil","label":"Gültig bis","type":"date","optional":false},{"key":"recipients","label":"Verknüpfte Empfänger hinzufügen","type":"people","optional":false},{"key":"decision","label":"Freigabeentscheidung zum angezeigten Planinhalt","type":"text","optional":false}]},"acknowledge":{"keys":["publishEventId","recipient","channel","decision"],"fields":[{"key":"publishEventId","label":"Eigene aktuelle Veröffentlichung","type":"event","eventKinds":["publish"],"optional":false},{"key":"recipient","label":"Eigene empfangende Person","type":"person","optional":false},{"key":"channel","label":"Empfangskanal","type":"text","optional":false},{"key":"decision","label":"Persönliche Bestätigung des angezeigten Planinhalts","type":"text","optional":false}]},"trip_start":{"keys":["tour","vehicle","maintenance","driver","startedAt","startKm","purpose","handover","maintenanceEventId"],"fields":[{"key":"tour","label":"Tourfassung","type":"source","sourceKinds":["tour"]},{"key":"vehicle","label":"Übernommenes Fahrzeug","type":"source","sourceKinds":["vehicle"]},{"key":"maintenanceEventId","label":"Aktuelle ausdrückliche Fahrzeugfreigabe","type":"event","eventKinds":["maintenance"],"optional":false},{"key":"driver","label":"Eigene fahrende Person","type":"person","optional":false},{"key":"startedAt","label":"Tatsächlicher Fahrtbeginn","type":"time","optional":false},{"key":"startKm","label":"Tatsächlicher Kilometerstand bei Übernahme","type":"number","optional":false},{"key":"purpose","label":"Fahrtzweck","type":"text","optional":false},{"key":"handover","label":"Übernahme und tatsächlicher Zustand","type":"text","optional":false}]},"trip_finish":{"keys":["tripStartEventId","endedAt","endKm","returnNotes"],"fields":[{"key":"tripStartEventId","label":"Eigene offene Fahrt","type":"event","eventKinds":["trip_start"],"optional":false},{"key":"endedAt","label":"Tatsächliches Fahrtende","type":"time","optional":false},{"key":"endKm","label":"Tatsächlicher Kilometerstand bei Rückgabe","type":"number","optional":false},{"key":"returnNotes","label":"Rückgabe und tatsächliche Auffälligkeiten","type":"text","optional":false}]},"maintenance":{"keys":["vehicle","maintenance","dueAt","status","outcome","replacement","decision"],"fields":[{"key":"vehicle","label":"Fahrzeug","type":"source","sourceKinds":["vehicle"]},{"key":"dueAt","label":"Nächste Prüffrist oder dokumentierter Fälligkeitstermin","type":"time","optional":false},{"key":"status","label":"Eigenes dokumentiertes Ergebnis","type":"choice","options":[{"key":"due","label":"Prüfung fällig"},{"key":"out_of_service","label":"Fahrzeug sperren"},{"key":"completed","label":"Prüfung durchgeführt"},{"key":"cleared","label":"Ausdrückliche befristete Freigabe"}]},{"key":"outcome","label":"Tatsächlicher Prüf- oder Wartungsbeleg und Ergebnis","type":"text","optional":false},{"key":"replacement","label":"Anderes Ersatzfahrzeug","type":"source","sourceKinds":["vehicle"],"optional":true},{"key":"decision","label":"Verantwortliche Entscheidung über Sperre oder Freigabe","type":"text","optional":false}]},"correct":{"keys":["targetId","reason"],"fields":[{"key":"targetId","label":"Zu berichtigendes Original","type":"event","eventKinds":[],"optional":false},{"key":"reason","label":"Berichtigungsgrund; das Original bleibt erhalten","type":"text","optional":false}]},"additional_request":{"keys":["stop","admission","category","provider","contact","contractReference","requestText"],"fields":[{"key":"stop","label":"Zugehöriger Besuch","type":"source","sourceKinds":["stop"]},{"key":"admission","label":"Zugehörige Aufnahme","type":"source","sourceKinds":["admission"]},{"key":"category","label":"Zusatzleistung","type":"choice","options":[{"key":"alarm","label":"Hausnotruf"},{"key":"support","label":"Weitere Unterstützung"},{"key":"other","label":"Andere Zusatzleistung"}]},{"key":"provider","label":"Anbieter","type":"text","optional":false},{"key":"contact","label":"Kontakt und vereinbarte Notfallkette","type":"text","optional":false},{"key":"contractReference","label":"Tatsächliche Vertrags- oder Anfragereferenz","type":"text","optional":false},{"key":"requestText","label":"Anfrage, Zuständigkeit und offene Schritte","type":"text","optional":false}]},"additional_response":{"keys":["requestEventId","receivedAt","result","evidenceReference","decision"],"fields":[{"key":"requestEventId","label":"Ursprüngliche Zusatzleistungsanfrage","type":"event","eventKinds":["additional_request"],"optional":false},{"key":"receivedAt","label":"Tatsächlicher Eingang der Antwort","type":"time","optional":false},{"key":"result","label":"Belegtes Antwortergebnis","type":"choice","options":[{"key":"accepted","label":"Anbieter hat zugesagt"},{"key":"rejected","label":"Zurückgewiesen"},{"key":"stopped","label":"Anbieter hat Beendigung bestätigt"}]},{"key":"evidenceReference","label":"Originalreferenz der Anbieterantwort","type":"text","optional":false},{"key":"decision","label":"Konsequenz und noch offene Schritte","type":"text","optional":false}]},"meal_request":{"keys":["stop","admission","provider","serviceDate","portions","dietNotes","requestReference"],"fields":[{"key":"stop","label":"Zugehöriger Besuch","type":"source","sourceKinds":["stop"]},{"key":"admission","label":"Zugehörige Aufnahme","type":"source","sourceKinds":["admission"]},{"key":"provider","label":"Essensanbieter","type":"text","optional":false},{"key":"serviceDate","label":"Konkreter Liefertag","type":"date","optional":false},{"key":"portions","label":"Angefragte Portionen","type":"number","optional":false},{"key":"dietNotes","label":"Vereinbarte Kost oder ausdrücklich fehlende Angaben","type":"text","optional":false},{"key":"requestReference","label":"Originalreferenz der Anfrage","type":"text","optional":false}]},"meal_delivery":{"keys":["requestEventId","deliveredAt","portions","result","receivedBy","deviation"],"fields":[{"key":"requestEventId","label":"Ursprüngliche Essensanfrage","type":"event","eventKinds":["meal_request"],"optional":false},{"key":"deliveredAt","label":"Tatsächlicher Lieferzeitpunkt","type":"time","optional":false},{"key":"portions","label":"Tatsächlich gelieferte Portionen","type":"number","optional":false},{"key":"result","label":"Tatsächliches Ergebnis","type":"choice","options":[{"key":"delivered","label":"Offene Menge vollständig geliefert"},{"key":"partial","label":"Teilmenge geliefert"},{"key":"not_delivered","label":"Nicht geliefert"}]},{"key":"receivedBy","label":"Tatsächlich annehmende Person oder Grund fehlender Annahme","type":"text","optional":false},{"key":"deviation","label":"Abweichung oder ausdrücklicher Vermerk ohne Auffälligkeit","type":"text","optional":false}]}}$spec$::jsonb->k$$;
create or replace function care_tour_planning_private.is_id(v jsonb)returns boolean language sql immutable set search_path='' as $$select jsonb_typeof(v)='string'and(v#>>'{}')~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'$$;
create or replace function care_tour_planning_private.is_time(v jsonb)returns boolean language plpgsql immutable set search_path='' as $$
declare x text:=v#>>'{}';d timestamptz;begin
 if jsonb_typeof(v)is distinct from 'string'or x!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'then return false;end if;d:=x::timestamptz;return isfinite(d);exception when others then return false;end$$;
create or replace function care_tour_planning_private.is_day(v jsonb)returns boolean language plpgsql immutable set search_path='' as $$
declare x text:=v#>>'{}';begin return jsonb_typeof(v)='string'and x~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'and to_char(x::date,'YYYY-MM-DD')=x;exception when others then return false;end$$;
create or replace function care_tour_planning_private.in_shift(s jsonb,start_at timestamptz,end_at timestamptz)returns boolean language plpgsql immutable set search_path='' as $$
declare a timestamp;b timestamp;begin
 if s->>'status'not in('draft','published','confirmed','in_progress')then return false;end if;
 a:=(s->>'shift_date')::date+(s->>'start_time')::time;b:=(s->>'shift_date')::date+(s->>'end_time')::time;
 if b<=a then b:=b+interval '1 day';end if;
 return start_at at time zone 'Europe/Berlin'>=a and end_at at time zone 'Europe/Berlin'<=b and end_at>start_at;
 exception when others then return false;
end$$;
create or replace function care_tour_planning_private.walk_current(v jsonb,src jsonb,persons jsonb)returns void language plpgsql set search_path='' as $$
declare x jsonb;begin
 if jsonb_typeof(v)='array'then for x in select value from jsonb_array_elements(v)loop perform care_tour_planning_private.walk_current(x,src,persons);end loop;
 elsif jsonb_typeof(v)='object'then
 if v?'snapshot'then if not exists(select 1 from jsonb_array_elements(src)x where x=v)then raise exception using errcode='40001',message='Ein vollständiger Quellbeleg wurde geändert.';end if;
 elsif v?'roleKey'then if not exists(select 1 from jsonb_array_elements(persons)x where x=v)then raise exception using errcode='40001',message='Eine beteiligte Person wurde geändert.';end if;
 else for x in select value from jsonb_each(v)loop perform care_tour_planning_private.walk_current(x,src,persons);end loop;end if;end if;
end$$;
create or replace function care_tour_planning_private.personnel_check(proof jsonb,person jsonb,qualification jsonb,activity text,start_at timestamptz,end_at timestamptz)returns void language plpgsql set search_path='' as $$
declare raw jsonb:=proof->'snapshot';h jsonb:=raw->'history';events jsonb:='[]';e jsonb;emp jsonb;q jsonb;exit_event jsonb;sick jsonb;returned jsonb;seq bigint:=0;prev text;first_day text:=to_char(start_at at time zone 'Europe/Berlin','YYYY-MM-DD');last_day text:=to_char(end_at at time zone 'Europe/Berlin','YYYY-MM-DD');begin
 if proof->>'id'is distinct from person->>'id'or qualification#>>'{snapshot,employee_id}'is distinct from person->>'id'or h->>'employeeId'is distinct from person->>'id'or h->>'tenantId'is distinct from person->>'tenantId'or jsonb_typeof(h->'events')is distinct from 'array'or(h->>'count')::integer<>jsonb_array_length(h->'events')then raise exception using errcode='23514',message='Personalentscheidungen sind nicht vollständig zugeordnet.';end if;
 for e in select value from jsonb_array_elements(h->'events')loop
 if(e->>'sequence')::bigint<>seq+1 or(e->>'previousId')is distinct from prev or e#>>'{command,eventId}'is distinct from e->>'id'or e#>>'{command,employeeId}'is distinct from person->>'id'or e#>>'{command,tenantId}'is distinct from person->>'tenantId'then raise exception using errcode='23514',message='Die Personalentscheidungskette ist unvollständig.';end if;
 seq:=seq+1;prev:=e->>'id';
 if e#>>'{command,kind}'<>'correct'and not exists(select 1 from jsonb_array_elements(h->'events')z where z#>>'{command,kind}'='correct'and z#>>'{command,payload,targetId}'=e->>'id')then events:=events||jsonb_build_array(e);end if;end loop;
 if h->>'headId'is distinct from prev then raise exception using errcode='23514',message='Personalentscheidungskopf fehlt.';end if;
 select x into emp from jsonb_array_elements(events)x where x#>>'{command,kind}'='employment'order by(x->>'sequence')::bigint desc limit 1;
 select x into exit_event from jsonb_array_elements(events)x where x#>>'{command,kind}'='offboard'order by(x->>'sequence')::bigint desc limit 1;
 if emp is null or care_tour_planning_private.is_day(emp#>'{command,payload,validFrom}')is not true or emp#>'{command,payload,validUntil}'<>'null'::jsonb and care_tour_planning_private.is_day(emp#>'{command,payload,validUntil}')is not true or exit_event is not null and care_tour_planning_private.is_day(exit_event#>'{command,payload,exitDate}')is not true or emp#>>'{command,payload,employee,id}'is distinct from person->>'id'or emp#>>'{command,payload,validFrom}'>first_day or emp#>>'{command,payload,validFrom}'is null or coalesce(emp#>>'{command,payload,validUntil}',last_day)<last_day
 or exit_event is not null and exit_event#>>'{command,payload,exitDate}'<=last_day and not((emp->>'sequence')::bigint>(exit_event->>'sequence')::bigint and emp#>>'{command,payload,validFrom}'>exit_event#>>'{command,payload,exitDate}')then raise exception using errcode='23514',message='Gültige Beschäftigung für den gesamten Zeitraum fehlt.';end if;
 select x->'command'->'payload'into q from jsonb_array_elements(events)x where x#>>'{command,kind}'='qualification'and x#>>'{command,payload,qualification,id}'=qualification->>'id'order by(x->>'sequence')::bigint desc limit 1;
 if q is null or care_tour_planning_private.is_day(q->'validFrom')is not true or care_tour_planning_private.is_day(q->'validUntil')is not true or q->>'result'is distinct from 'verified'or q->>'activity'is distinct from activity or q->>'validFrom'is null or q->>'validUntil'is null or q->>'validFrom'>first_day or q->>'validUntil'<last_day or q->'qualification'is distinct from qualification
 or not exists(select 1 from jsonb_array_elements(raw->'qualifications')x where x=q->'qualification')or not exists(select 1 from jsonb_array_elements(raw->'documents')x where x=q->'document')or qualification#>>'{snapshot,document_id}'is distinct from q#>>'{document,id}'or qualification#>>'{snapshot,status}'not in('valid','expires_soon')then raise exception using errcode='23514',message='Aktuelle konkrete Qualifikation und unverändertes Originaldokument fehlen.';end if;
 if exists(select 1 from jsonb_array_elements(events)x where x#>>'{command,kind}'='absence'and(x#>>'{command,payload,validFrom}')::timestamptz<end_at and coalesce((x#>>'{command,payload,validUntil}')::timestamptz,'infinity'::timestamptz)>start_at)then raise exception using errcode='23514',message='Dokumentierte Abwesenheit überschneidet die Planung.';end if;
 select x into sick from jsonb_array_elements(events)x where x#>>'{command,kind}'='absence'and x#>>'{command,payload,category}'='sick'and(x#>>'{command,payload,validUntil}')::timestamptz<=start_at order by(x#>>'{command,payload,validUntil}')::timestamptz desc,(x->>'sequence')::bigint desc limit 1;
 if sick is not null then
 select x->'command'->'payload'into returned from jsonb_array_elements(events)x where x#>>'{command,kind}'='return_decision'and x#>>'{command,payload,absence,id}'=sick#>>'{command,payload,absence,id}'order by(x->>'sequence')::bigint desc limit 1;
 if returned is null or returned->>'decision'is distinct from 'fit'or returned->'absence'is distinct from sick#>'{command,payload,absence}'or(returned->>'validFrom')::timestamptz>start_at or(returned->>'validUntil')::timestamptz<end_at then raise exception using errcode='23514',message='Aktuelle uneingeschränkte Rückkehrentscheidung fehlt.';end if;end if;
end$$;
create or replace function care_tour_planning_private.require_maintenance(t uuid,p uuid,event_id text,vehicle jsonb,start_at timestamptz,end_at timestamptz)returns void language plpgsql set search_path='' as $$
declare e care_tour_planning_private.events%rowtype;begin
 select*into e from care_tour_planning_private.live_events(t,p)x where x.kind='maintenance'and x.command#>>'{payload,vehicle,id}'=vehicle->>'id'order by x.sequence desc limit 1;
 if e.id is null or e.command->>'version'is distinct from '2026-10-16.2'or e.id::text is distinct from event_id or e.command#>>'{payload,status}'is distinct from 'cleared'or e.command#>'{payload,vehicle}'is distinct from vehicle or(e.command#>>'{payload,dueAt}')::timestamptz<=end_at or e.occurred_at>start_at then raise exception using errcode='23514',message='Ausdrückliche aktuelle Fahrzeugfreigabe für diesen Zeitraum fehlt.';end if;
end$$;
create or replace function care_tour_planning_private.packet(t uuid,p uuid)returns jsonb language plpgsql set search_path='' as $$
declare v care_tour_planning_private.events%rowtype;a care_tour_planning_private.events%rowtype;stops jsonb;begin
 select*into v from care_tour_planning_private.live_events(t,p)x where x.kind='plan_version'order by x.sequence desc limit 1;
 select*into a from care_tour_planning_private.live_events(t,p)x where x.kind='assignment'order by x.sequence desc limit 1;
 if v.id is null or a.id is null or a.command->>'version'<>'2026-10-16.2'then raise exception using errcode='23514',message='Aktuelle vollständige Planfassung fehlt.';end if;
 select coalesce(jsonb_agg(jsonb_build_object('eventId',z.id,'stopId',z.command#>>'{payload,stop,id}','clientId',z.command#>>'{payload,stop,snapshot,client_id}','clientLabel',case when nullif(btrim(z.command#>>'{payload,stop,snapshot,client_name_snapshot}'),'')is null then null else z.command#>>'{payload,stop,snapshot,client_name_snapshot}'end,'windowStart',z.command#>>'{payload,windowStart}','windowEnd',z.command#>>'{payload,windowEnd}','serviceType',z.command#>>'{payload,serviceType}','frequency',z.command#>>'{payload,frequency}')order by z.command#>>'{payload,stop,id}'),'[]')into stops
 from(select distinct on(x.command#>>'{payload,stop,id}')x.*from care_tour_planning_private.live_events(t,p)x where x.kind='visit_binding'order by x.command#>>'{payload,stop,id}',x.sequence desc)z;
 return jsonb_build_object('versionEventId',v.id,'assignmentEventId',a.id,'versionLabel',v.command#>>'{payload,versionLabel}','validFrom',v.command#>>'{payload,validFrom}','validUntil',v.command#>>'{payload,validUntil}','startedAt',a.command#>>'{payload,startedAt}','endedAt',a.command#>>'{payload,endedAt}','activity',a.command#>>'{payload,activity}','accessSummary',a.command#>>'{payload,accessSummary}','vehicleId',a.command#>'{payload,vehicle,id}','stops',stops);
end$$;
create or replace function care_tour_planning_private.publication_current(t uuid,p uuid,pub uuid)returns boolean language plpgsql security definer set search_path='' as $$
declare e care_tour_planning_private.events%rowtype;a care_tour_planning_private.events%rowtype;src jsonb;persons jsonb;v record;begin
 select*into e from care_tour_planning_private.live_events(t,p)x where x.kind='publish'order by x.sequence desc limit 1;
 if e.id is distinct from pub or e.command->>'version'is distinct from '2026-10-16.2'or exists(select 1 from care_tour_planning_private.events x where x.tenant_id=t and x.plan_id=p and x.sequence>e.sequence and x.kind not in('acknowledge','trip_start','trip_finish','additional_request','additional_response','meal_request','meal_delivery'))then return false;end if;
 src:=care_tour_planning_private.sources(t,p);persons:=care_tour_planning_private.people(t);
 select*into a from care_tour_planning_private.live_events(t,p)x where x.id::text=e.command#>>'{payload,packet,assignmentEventId}'and x.kind='assignment';
 if a.id is null or care_tour_planning_private.packet(t,p)is distinct from e.command#>'{payload,packet}'then return false;end if;
 perform care_tour_planning_private.walk_current(a.command->'payload',src,persons);
 perform care_tour_planning_private.walk_current(e.command#>'{payload,tour}',src,persons);
 for v in select distinct on(x.command#>>'{payload,stop,id}')x.*from care_tour_planning_private.live_events(t,p)x where x.kind='visit_binding'order by x.command#>>'{payload,stop,id}',x.sequence desc loop perform care_tour_planning_private.walk_current(v.command->'payload',src,persons);end loop;
 if exists(select 1 from jsonb_array_elements(src)s where s->>'kind'='stop'and coalesce(s#>>'{snapshot,status}','')not in('cancelled','archived')and not exists(select 1 from jsonb_array_elements(e.command#>'{payload,packet,stops}')z where z->>'stopId'=s->>'id'))then return false;end if;
 return true;exception when others then return false;
end$$;
create or replace function care_tour_planning_private.validate_command(p_tenant uuid,p_plan uuid,p_actor uuid,p_command jsonb)returns void language plpgsql security definer set search_path='' as $$
declare k text:=p_command->>'kind';p jsonb:=p_command->'payload';spec jsonb:=care_tour_planning_private.payload_spec(k);f jsonb;v jsonb;x jsonb;r jsonb;src jsonb;persons jsonb;name text;kind text;optional boolean;
 a care_tour_planning_private.events%rowtype;version_event care_tour_planning_private.events%rowtype;target care_tour_planning_private.events%rowtype;rule_event care_tour_planning_private.events%rowtype;
 start_at timestamptz;end_at timestamptz;duration_minutes numeric;previous_end timestamptz;remaining integer;begin
 if jsonb_typeof(p_command)is distinct from 'object'or(select count(*)from jsonb_object_keys(p_command))<>11 or not(p_command?&array['version','requestId','eventId','tenantId','planId','actorId','expectedHeadId','kind','occurredAt','note','payload'])or octet_length(p_command::text)>6000000
 or p_command->>'version'is distinct from '2026-10-16.2'or p_command->>'tenantId'is distinct from p_tenant::text or p_command->>'planId'is distinct from p_plan::text or p_command->>'actorId'is distinct from p_actor::text or spec is null then raise exception using errcode='22023',message='Aktuelle vollständige Planungsanfrage fehlt.';end if;
 foreach name in array array['requestId','eventId','tenantId','planId','actorId']loop if care_tour_planning_private.is_id(p_command->name)is not true then raise exception using errcode='22023',message='Originalkennung ungültig.';end if;end loop;
 if p_command->>'requestId'=p_command->>'eventId'or not(p_command->'expectedHeadId'='null'::jsonb or care_tour_planning_private.is_id(p_command->'expectedHeadId'))or care_tour_planning_private.is_time(p_command->'occurredAt')is not true or(p_command->>'occurredAt')::timestamptz>clock_timestamp()
 or jsonb_typeof(p_command->'note')is distinct from 'string'or length(btrim(p_command->>'note'))=0 or length(p_command->>'note')>4000 then raise exception using errcode='22023',message='Tatsächliche Zeit, Anlass oder Originalkopf fehlen.';end if;
 if jsonb_typeof(p)is distinct from 'object'or(select count(*)from jsonb_object_keys(p))<>jsonb_array_length(spec->'keys')or exists(select 1 from jsonb_array_elements_text(spec->'keys')z where not p?z)then raise exception using errcode='22023',message='Felder sind unvollständig oder fremd.';end if;
 src:=case when k='acknowledge'then '[]'::jsonb else care_tour_planning_private.sources(p_tenant,p_plan)end;persons:=care_tour_planning_private.people(p_tenant);
 for f in select value from jsonb_array_elements(spec->'fields')loop
 name:=f->>'key';kind:=f->>'type';v:=p->name;optional:=coalesce((f->>'optional')::boolean,false);
 if optional and v='null'::jsonb then continue;end if;
 if kind='source'then
 if jsonb_typeof(v)is distinct from 'object'or not exists(select 1 from jsonb_array_elements_text(f->'sourceKinds')z where z=v->>'kind')or not exists(select 1 from jsonb_array_elements(src)z where z=v)then raise exception using errcode='40001',message='Das ausgewählte vollständige Original fehlt oder wurde geändert.';end if;
 elsif kind='person'then perform care_tour_planning_private.assert_person(p_tenant,v);
 elsif kind='people'then
 if jsonb_typeof(v)is distinct from 'array'or jsonb_array_length(v)<1 or jsonb_array_length(v)>100 then raise exception using errcode='22023',message='Adressierte Personen fehlen.';end if;
 for x in select value from jsonb_array_elements(v)loop perform care_tour_planning_private.assert_person(p_tenant,x);if care_tour_planning_private.is_id(x->'profileId')is not true then raise exception using errcode='23514',message='Empfangendes Konto nicht verknüpft.';end if;end loop;
 if(select count(distinct x->>'id')from jsonb_array_elements(v)x)<>jsonb_array_length(v)or(select count(distinct x->>'profileId')from jsonb_array_elements(v)x)<>jsonb_array_length(v)then raise exception using errcode='22023',message='Empfangendes Konto ist doppelt adressiert.';end if;
 elsif kind='event'then if care_tour_planning_private.is_id(v)is not true then raise exception using errcode='22023',message='Genauer Originalereignisbezug fehlt.';end if;
 elsif kind='number'then if jsonb_typeof(v)is distinct from 'number'or(v#>>'{}')!~'^[0-9]+$'or(v#>>'{}')::numeric>case when name in('startKm','endKm')then 10000000 when name='portions'then 1000 else 1440 end or(v#>>'{}')::numeric<case when name in('capacityMinutes')or name='portions'and k='meal_request'then 1 else 0 end then raise exception using errcode='22023',message='Menge, Kapazität oder Kilometerstand ungültig.';end if;
 elsif kind='time'then if care_tour_planning_private.is_time(v)is not true then raise exception using errcode='22007',message='Vollständiger Zeitpunkt mit eindeutigem UTC-Abstand fehlt.';end if;
 elsif kind='date'then if care_tour_planning_private.is_day(v)is not true then raise exception using errcode='22007',message='Konkretes gültiges Datum fehlt.';end if;
 elsif kind='choice'then if jsonb_typeof(v)is distinct from 'string'or not exists(select 1 from jsonb_array_elements(f->'options')z where z->>'key'=v#>>'{}')then raise exception using errcode='22023',message='Eindeutige Auswahl fehlt.';end if;
 else if jsonb_typeof(v)is distinct from 'string'or length(btrim(v#>>'{}'))=0 or length(v#>>'{}')>4000 then raise exception using errcode='22023',message='Nachvollziehbare Pflichtangabe fehlt.';end if;end if;
 end loop;
 if p?'maintenance'and p->'maintenance'is distinct from case when p->'vehicle'='null'::jsonb then 'null'::jsonb else jsonb_set(p->'vehicle','{kind}','"maintenance"')end then raise exception using errcode='23514',message='Fahrzeug und unveränderte Wartungsgegenstandsquelle passen nicht zusammen.';end if;
 if k in('plan_version','publish')and(p->>'validFrom'>p->>'validUntil'or(p#>>'{tour,snapshot,tour_date}')::date not between(p->>'validFrom')::date and(p->>'validUntil')::date)then raise exception using errcode='23514',message='Die gültige Planfassung muss den ursprünglichen Tourtag abdecken.';end if;
 if k in('rule_review','assignment','replan','visit_binding')then
 start_at:=(p->>case when k='visit_binding'then 'windowStart'else 'startedAt'end)::timestamptz;end_at:=(p->>case when k='visit_binding'then 'windowEnd'else 'endedAt'end)::timestamptz;
 if end_at<=start_at then raise exception using errcode='23514',message='Ende muss nach Beginn liegen.';end if;end if;
 if k='rule_review'then
 if(p->>'breakMinutes')::numeric>=extract(epoch from(end_at-start_at))/60 or p->>'result'='compliant'and(p#>'{rule,snapshot}'is distinct from p#>'{shift,snapshot}'or p#>>'{rule,id}'is distinct from p#>>'{shift,id}'or care_tour_planning_private.in_shift(p#>'{shift,snapshot}',start_at,end_at)is not true or(p->>'breakMinutes')::integer<(p#>>'{shift,snapshot,break_minutes}')::integer)then raise exception using errcode='23514',message='Konkrete Schichtvorgaben, Zeit oder Pause nicht gedeckt.';end if;
 elsif k='visit_binding'then
 if p#>>'{stop,snapshot,tour_id}'is distinct from p_plan::text or p#>>'{stop,snapshot,client_id}'is distinct from p#>>'{admission,snapshot,client_id}'or p#>>'{stop,snapshot,client_id}'is distinct from p#>>'{carePlan,snapshot,client_id}'or p->>'decision'not in('planned','blocked')or p->>'decision'='planned'and(p->>'continuity'<>'active'or p#>>'{admission,snapshot,status}'not in('active','admitted')or p#>>'{carePlan,snapshot,status}'not in('active','approved','published'))then raise exception using errcode='23514',message='Besuch, aktive Versorgung und eigene Planoriginale widersprechen sich.';end if;
 elsif k in('assignment','replan')then
 if to_char(start_at at time zone 'Europe/Berlin','YYYY-MM-DD')is distinct from care_tour_planning_private.plan_original(p_tenant,p_plan)->>'tour_date'then raise exception using errcode='23514',message='Zuordnung gehört nicht zum ursprünglichen Tourtag.';end if;
 for x in select value from jsonb_array_elements(case when k='assignment'then jsonb_build_array(p->'primary',p->'secondary')else jsonb_build_array(p->'replacement')end)where value<>'null'::jsonb loop
 if not exists(select 1 from jsonb_array_elements(src)z where z->>'kind'='shift'and z#>>'{snapshot,employee_id}'=x->>'id'and care_tour_planning_private.in_shift(z->'snapshot',start_at,end_at))and not exists(select 1 from jsonb_array_elements(src)z where z->>'kind'='availability'and z#>>'{snapshot,employee_id}'=x->>'id'and(z#>>'{snapshot,starts_at}')::timestamptz<=start_at and(z#>>'{snapshot,ends_at}')::timestamptz>=end_at)then raise exception using errcode='23514',message='Native Schicht oder ausdrückliche Verfügbarkeit fehlt.';end if;
 if exists(select 1 from jsonb_array_elements(src)z where z->>'kind'='absence'and z#>>'{snapshot,employee_id}'=x->>'id'and z#>>'{snapshot,status}'not in('rejected','cancelled')and(z#>>'{snapshot,starts_at}')::timestamptz<end_at and(z#>>'{snapshot,ends_at}')::timestamptz>start_at)then raise exception using errcode='23514',message='Native Abwesenheit überschneidet die Zuordnung.';end if;
 end loop;
 for x in select value->'snapshot'from jsonb_array_elements(src)where value->>'kind'='resource'and value#>>'{snapshot,kind}'in('assignment','replan')loop
 r:=x#>'{command,payload}';
 if exists(select 1 from jsonb_array_elements(case when k='assignment'then jsonb_build_array(p->'primary',p->'secondary')else jsonb_build_array(p->'replacement')end)who where who<>'null'::jsonb and who->>'id'in(r#>>'{primary,id}',r#>>'{secondary,id}',r#>>'{replacement,id}'))or p#>>'{vehicle,id}'=r#>>'{vehicle,id}'then
 if r->>'startedAt'is null and x->>'tour_date'=to_char(start_at at time zone 'Europe/Berlin','YYYY-MM-DD')or(r->>'startedAt')::timestamptz<end_at and(r->>'endedAt')::timestamptz>start_at then raise exception using errcode='23514',message='Person oder Fahrzeug ist bereits einer anderen Tour zugeordnet.';end if;end if;end loop;
 if k='assignment'then
 if p#>>'{shift,snapshot,employee_id}'is distinct from p#>>'{primary,id}'or care_tour_planning_private.in_shift(p#>'{shift,snapshot}',start_at,end_at)is not true or(p->>'travelMinutes')::integer>=(p->>'capacityMinutes')::integer or(p->>'capacityMinutes')::numeric>extract(epoch from(end_at-start_at))/60 then raise exception using errcode='23514',message='Schicht, Person, Zeitraum und Kapazität passen nicht zusammen.';end if;
 perform care_tour_planning_private.personnel_check(p->'primaryPersonnel',p->'primary',p->'primaryQualification',p->>'activity',start_at,end_at);
 if p->'secondary'<>'null'::jsonb then
 if p#>>'{secondary,id}'=p#>>'{primary,id}'then raise exception using errcode='23514',message='Doppelbesetzung benötigt verschiedene Personen.';end if;
 perform care_tour_planning_private.personnel_check(p->'secondaryPersonnel',p->'secondary',p->'secondaryQualification',p->>'activity',start_at,end_at);
 elsif p->'secondaryQualification'<>'null'::jsonb or p->'secondaryPersonnel'<>'null'::jsonb then raise exception using errcode='23514',message='Zweite Person und Nachweise widersprechen sich.';end if;
 select*into version_event from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='plan_version'order by z.sequence desc limit 1;
 if version_event.id is null or version_event.id::text is distinct from p->>'planVersionEventId'or version_event.command#>'{payload,tour}'is distinct from p->'tour'or version_event.command#>>'{payload,validFrom}'>to_char(start_at at time zone 'Europe/Berlin','YYYY-MM-DD')or version_event.command#>>'{payload,validUntil}'<to_char(end_at at time zone 'Europe/Berlin','YYYY-MM-DD')then raise exception using errcode='23514',message='Aktuelle identische gültige Planfassung fehlt.';end if;
 select*into rule_event from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='rule_review'and z.command#>>'{payload,shift,id}'=p#>>'{shift,id}'order by z.sequence desc limit 1;
 if rule_event.id is null or rule_event.command->>'version'is distinct from '2026-10-16.2'or rule_event.command#>>'{payload,result}'is distinct from 'compliant'or rule_event.command#>'{payload,shift}'is distinct from p->'shift'or(rule_event.command#>>'{payload,startedAt}')::timestamptz>start_at or(rule_event.command#>>'{payload,endedAt}')::timestamptz<end_at then raise exception using errcode='23514',message='Aktuelle konkrete regelkonforme Schichtprüfung fehlt.';end if;
 if p->'vehicle'='null'::jsonb then if p->'maintenanceEventId'<>'null'::jsonb then raise exception using errcode='23514',message='Fahrzeugbezug widersprüchlich.';end if;else perform care_tour_planning_private.require_maintenance(p_tenant,p_plan,p->>'maintenanceEventId',p->'vehicle',start_at,end_at);end if;
 else
 perform care_tour_planning_private.personnel_check(p->'replacementPersonnel',p->'replacement',p->'replacementQualification',p->>'activity',start_at,end_at);
 select*into a from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='assignment'order by z.sequence desc limit 1;
 if p#>>'{cause,snapshot,status}'in('rejected','cancelled')or(p#>>'{cause,snapshot,starts_at}')::timestamptz>=end_at or(p#>>'{cause,snapshot,ends_at}')::timestamptz<=start_at or a.id is null or a.id::text is distinct from p->>'previousAssignmentEventId'or a.command->>'version'<>'2026-10-16.2'or a.command#>'{payload,tour}'is distinct from p->'tour'or a.command#>>'{payload,primary,id}'is distinct from p#>>'{cause,snapshot,employee_id}'or p#>>'{replacement,id}'=a.command#>>'{payload,primary,id}'or p->>'activity'is distinct from a.command#>>'{payload,activity}'or start_at<(a.command#>>'{payload,startedAt}')::timestamptz or end_at>(a.command#>>'{payload,endedAt}')::timestamptz or p#>>'{stop,snapshot,tour_id}'is distinct from p_plan::text or p#>>'{stop,snapshot,status}'in('arrived','in_progress','completed')then raise exception using errcode='23514',message='Aktuelle Ausfallzuordnung, Ersatzperson oder noch nicht begonnener Besuch fehlen.';end if;
 end if;
 elsif k='publish'then
 select*into version_event from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='plan_version'order by z.sequence desc limit 1;
 select*into a from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='assignment'order by z.sequence desc limit 1;
 if version_event.id is null or version_event.id::text is distinct from p->>'planVersionEventId'or a.id is null or a.command->>'version'is distinct from '2026-10-16.2'or a.command#>>'{payload,planVersionEventId}'is distinct from version_event.id::text
 or version_event.command#>'{payload,tour}'is distinct from p->'tour'or version_event.command#>>'{payload,versionLabel}'is distinct from p->>'versionLabel'or version_event.command#>>'{payload,validFrom}'is distinct from p->>'validFrom'or version_event.command#>>'{payload,validUntil}'is distinct from p->>'validUntil'or p->'packet'is distinct from care_tour_planning_private.packet(p_tenant,p_plan)then raise exception using errcode='23514',message='Aktuelle identische Planfassung, vollständige Zuordnung oder adressierter Inhalt fehlen.';end if;
 if exists(select 1 from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.sequence>a.sequence and z.kind in('rule_review','visit_binding','preference_exception','series_exception','replan','maintenance'))then raise exception using errcode='23514',message='Nach Änderungen ist eine neue vollständige Zuordnungsprüfung erforderlich.';end if;
 perform care_tour_planning_private.walk_current(a.command->'payload',src,persons);
 for x in select value from jsonb_array_elements(jsonb_build_array(a.command#>'{payload,primary}',a.command#>'{payload,secondary}'))where value<>'null'::jsonb loop if not exists(select 1 from jsonb_array_elements(p->'recipients')z where z->>'id'=x->>'id'and z->>'profileId'is not null)then raise exception using errcode='23514',message='Eine zugeordnete Person ist nicht persönlich adressiert.';end if;end loop;
 duration_minutes:=(a.command#>>'{payload,travelMinutes}')::numeric;
 for x in select care_tour_planning_private.event_json(z)from(select distinct on(e.command#>>'{payload,stop,id}')e.*from care_tour_planning_private.live_events(p_tenant,p_plan)e where e.kind='visit_binding'order by e.command#>>'{payload,stop,id}',e.sequence desc)z order by(z.command#>>'{payload,windowStart}')::timestamptz loop
 r:=x#>'{command,payload}';perform care_tour_planning_private.walk_current(r,src,persons);
 start_at:=(r->>'windowStart')::timestamptz;end_at:=(r->>'windowEnd')::timestamptz;
 if x#>>'{command,version}'is distinct from '2026-10-16.2'or r->>'continuity'is distinct from 'active'or r->>'decision'is distinct from 'planned'or start_at<(a.command#>>'{payload,startedAt}')::timestamptz or end_at>(a.command#>>'{payload,endedAt}')::timestamptz or start_at<previous_end then raise exception using errcode='23514',message='Besuchsbindung gesperrt, überlappend oder außerhalb der Zuordnungszeit.';end if;
 previous_end:=end_at;duration_minutes:=duration_minutes+extract(epoch from(end_at-start_at))/60;
 end loop;
 if previous_end is null or duration_minutes>(a.command#>>'{payload,capacityMinutes}')::numeric or exists(select 1 from jsonb_array_elements(src)s where s->>'kind'='stop'and coalesce(s#>>'{snapshot,status}','')not in('cancelled','archived')and not exists(select 1 from jsonb_array_elements(p#>'{packet,stops}')z where z->>'stopId'=s->>'id'))then raise exception using errcode='23514',message='Vollständige Besuchsmenge oder ausreichende Kapazität fehlen.';end if;
 if exists(select 1 from(select distinct on(z.command#>>'{payload,stop,id}')z.*from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='preference_exception'order by z.command#>>'{payload,stop,id}',z.sequence desc)z where z.command#>>'{payload,priority}'='required'and z.command#>>'{payload,outcome}'='deviation')then raise exception using errcode='23514',message='Verbindliche Vereinbarung noch nicht geklärt.';end if;
 elsif k='acknowledge'then
 select*into target from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='publish'and z.id::text=p->>'publishEventId';
 if target.id is null or care_tour_planning_private.publication_current(p_tenant,p_plan,target.id)is not true or p#>>'{recipient,profileId}'is distinct from p_actor::text or not exists(select 1 from jsonb_array_elements(target.command#>'{payload,recipients}')z where z=p->'recipient')then raise exception using errcode='42501',message='Nur die eigene aktuelle adressierte Fassung kann empfangen werden.';end if;
 if exists(select 1 from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='acknowledge'and z.command#>>'{payload,publishEventId}'=target.id::text and z.command#>>'{payload,recipient,id}'=p#>>'{recipient,id}')then raise exception using errcode='23514',message='Eigener Empfang bereits bestätigt.';end if;
 elsif k='trip_start'then
 start_at:=(p->>'startedAt')::timestamptz;
 if p#>>'{driver,profileId}'is distinct from p_actor::text or start_at>(p_command->>'occurredAt')::timestamptz or p#>>'{vehicle,snapshot,ownership}'='private'and p#>>'{vehicle,snapshot,employee_id}'is distinct from p#>>'{driver,id}'then raise exception using errcode='42501',message='Eigene tatsächliche Fahrer- und Fahrzeugverknüpfung fehlt.';end if;
 perform care_tour_planning_private.require_maintenance(p_tenant,p_plan,p->>'maintenanceEventId',p->'vehicle',start_at,start_at);
 if exists(select 1 from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='trip_start'and z.command#>>'{payload,vehicle,id}'=p#>>'{vehicle,id}'and not exists(select 1 from care_tour_planning_private.live_events(p_tenant,p_plan)f where f.kind='trip_finish'and f.command#>>'{payload,tripStartEventId}'=z.id::text))or exists(select 1 from jsonb_array_elements(src)z where z->>'kind'='resource'and z#>>'{snapshot,kind}'='trip_start'and z#>>'{snapshot,command,payload,vehicle,id}'=p#>>'{vehicle,id}')or exists(select 1 from public.employee_logbook_trips z where z.tenant_id=p_tenant and z.vehicle_id::text=p#>>'{vehicle,id}'and z.status='recording')then raise exception using errcode='23514',message='Für dieses Fahrzeug ist bereits eine tatsächliche Fahrt offen.';end if;
 select*into target from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='trip_finish'and exists(select 1 from care_tour_planning_private.live_events(p_tenant,p_plan)s where s.kind='trip_start'and s.id::text=z.command#>>'{payload,tripStartEventId}'and s.command#>>'{payload,vehicle,id}'=p#>>'{vehicle,id}')order by z.sequence desc limit 1;
 if target.id is not null and((p->>'startKm')::integer<(target.command#>>'{payload,endKm}')::integer or start_at<(target.command#>>'{payload,endedAt}')::timestamptz)then raise exception using errcode='23514',message='Fahrtbeginn liegt vor der letzten Rückgabe.';end if;
 elsif k='trip_finish'then
 select*into target from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='trip_start'and z.id::text=p->>'tripStartEventId';
 if target.id is null or target.command#>>'{payload,driver,profileId}'is distinct from p_actor::text or(p->>'endedAt')::timestamptz<(target.command#>>'{payload,startedAt}')::timestamptz or(p->>'endedAt')::timestamptz>(p_command->>'occurredAt')::timestamptz or(p->>'endKm')::integer<(target.command#>>'{payload,startKm}')::integer or exists(select 1 from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='trip_finish'and z.command#>>'{payload,tripStartEventId}'=target.id::text)then raise exception using errcode='23514',message='Eigener Fahrtabschluss, Zeitpunkt oder Kilometerstand widersprechen dem offenen Original.';end if;
 elsif k='maintenance'then
 if p#>>'{vehicle,id}'=p#>>'{replacement,id}'or p->>'status'='cleared'and(p#>'{vehicle,snapshot,active}'is distinct from 'true'::jsonb or(p->>'dueAt')::timestamptz<=(p_command->>'occurredAt')::timestamptz)then raise exception using errcode='23514',message='Tatsächliche Fahrzeugfreigabe oder anderes Ersatzfahrzeug fehlen.';end if;
 elsif k='preference_exception'then if p#>>'{preference,snapshot,client_id}'is distinct from p#>>'{stop,snapshot,client_id}'then raise exception using errcode='23514',message='Vereinbarung gehört zu einem anderen Pflegefall.';end if;
 elsif k='series_exception'then
 if care_tour_planning_private.is_id(p->'occurrenceId')is not true or p->>'occurrenceId'is distinct from p#>>'{occurrence,id}'or p#>>'{occurrence,snapshot,tour_id}'is distinct from p_plan::text or p#>>'{series,snapshot,care_plan_id}'is distinct from p#>>'{carePlan,id}'or p#>>'{carePlan,snapshot,client_id}'is distinct from p#>>'{occurrence,snapshot,client_id}'or p->>'originalDate'is distinct from care_tour_planning_private.plan_original(p_tenant,p_plan)->>'tour_date'or p->>'action'='reschedule'and(p->'newDate'='null'::jsonb or p->>'newDate'=p->>'originalDate')or p->>'action'<>'reschedule'and p->'newDate'<>'null'::jsonb then raise exception using errcode='23514',message='Explizites Einzelvorkommen, Pflegefall oder Datumsentscheidung fehlen.';end if;
 elsif k in('additional_request','meal_request')then
 if p#>>'{stop,snapshot,tour_id}'is distinct from p_plan::text or p#>>'{stop,snapshot,client_id}'is distinct from p#>>'{admission,snapshot,client_id}'or k='meal_request'and p->>'serviceDate'is distinct from care_tour_planning_private.plan_original(p_tenant,p_plan)->>'tour_date'then raise exception using errcode='23514',message='Anfrage gehört nicht zum eigenen ursprünglichen Besuch und Tourtag.';end if;
 elsif k in('additional_response','meal_delivery')then
 select*into target from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.id::text=p->>'requestEventId'and z.kind=case when k='additional_response'then 'additional_request'else 'meal_request'end;
 if target.id is null or(p->>case when k='additional_response'then 'receivedAt'else 'deliveredAt'end)::timestamptz>(p_command->>'occurredAt')::timestamptz then raise exception using errcode='23514',message='Unveränderte ursprüngliche Anfrage oder tatsächlicher Belegzeitpunkt fehlen.';end if;
 if k='meal_delivery'then
 select(target.command#>>'{payload,portions}')::integer-coalesce(sum((z.command#>>'{payload,portions}')::integer),0)into remaining from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='meal_delivery'and z.command#>>'{payload,requestEventId}'=target.id::text;
 if remaining<=0 or(p->>'portions')::integer>remaining or(p->>'result'='not_delivered')is distinct from((p->>'portions')::integer=0)or p->>'result'='delivered'and(p->>'portions')::integer<>remaining or p->>'result'='partial'and(p->>'portions')::integer>=remaining then raise exception using errcode='23514',message='Tatsächliche Menge widerspricht der offenen Bestellmenge.';end if;end if;
 elsif k='correct'then
 select*into target from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.id::text=p->>'targetId';
 if target.id is null or target.kind='trip_start'and exists(select 1 from care_tour_planning_private.live_events(p_tenant,p_plan)z where z.kind='trip_finish'and z.command#>>'{payload,tripStartEventId}'=target.id::text)then raise exception using errcode='23514',message='Unberichtigtes Original fehlt oder ein tatsächlicher Fahrtabschluss würde gelöst.';end if;
 end if;
end$$;
create or replace function care_tour_planning_private.plan_access(t uuid,p uuid)returns void language plpgsql security definer set search_path='' as $$
declare cid uuid;begin
 if care_tour_planning_private.plan_original(t,p)is null then raise exception using errcode='42501',message='Eigene ursprüngliche Tour fehlt.';end if;
 for cid in select distinct s.client_id from public.care_tour_stops s where s.tenant_id=t and s.tour_id=p and s.client_id is not null loop perform care_private.assert_control_access(t,cid);end loop;
end$$;
create or replace function care_tour_planning_private.read_context(p_tenant uuid,p_actor uuid,p_plan uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare src jsonb;persons jsonb;h jsonb;begin
 perform care_tour_planning_private.actor(p_tenant,p_actor,false);perform care_tour_planning_private.plan_access(p_tenant,p_plan);
 src:=care_tour_planning_private.sources(p_tenant,p_plan);persons:=care_tour_planning_private.people(p_tenant);h:=care_tour_planning_private.history(p_tenant,p_plan);
 perform care_tour_planning_private.actor(p_tenant,p_actor,false);
 return jsonb_build_object('version','2026-10-16.2','tenantId',p_tenant,'planId',p_plan,'actorId',p_actor,'loadedAt',to_char(clock_timestamp()at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'plan',care_tour_planning_private.plan_original(p_tenant,p_plan),'sources',jsonb_build_object('count',jsonb_array_length(src),'rows',src),'people',jsonb_build_object('count',jsonb_array_length(persons),'rows',persons),'history',h);
end$$;
create or replace function care_tour_planning_private.read_plans(t uuid,a uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare rows jsonb;x uuid;begin
 perform care_tour_planning_private.actor(t,a,false);
 for x in select z.id from public.care_tours z where z.tenant_id=t loop perform care_tour_planning_private.plan_access(t,x);end loop;
 select coalesce(jsonb_agg(jsonb_build_object('id',z.id,'tenant_id',z.tenant_id,'tour_date',z.tour_date,'name',z.name,'employee_name_snapshot',z.employee_name_snapshot,'status',z.status,'updated_at',z.updated_at)order by z.tour_date desc,z.name,z.id),'[]')into rows from public.care_tours z where z.tenant_id=t;
 perform care_tour_planning_private.actor(t,a,false);
 return jsonb_build_object('version','2026-10-16.2','tenantId',t,'actorId',a,'count',jsonb_array_length(rows),'plans',rows);
end$$;
create or replace function care_tour_planning_private.receipt(p_event care_tour_planning_private.events)returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('version','2026-10-16.2','requestId',p_event.request_id,'command',p_event.command,'event',care_tour_planning_private.event_json(p_event))$$;
create or replace function care_tour_planning_private.read_inbox(t uuid,a uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare e care_tour_planning_private.events%rowtype;recipient jsonb;ack jsonb;head uuid;rows jsonb:='[]';begin
 perform care_tour_planning_private.recipient_actor(t,a,false);
 for e in select z.*from care_tour_planning_private.roots r join care_tour_planning_private.events z on z.tenant_id=r.tenant_id and z.plan_id=r.plan_id where r.tenant_id=t and z.kind='publish'order by z.recorded_at desc,z.id loop
 select x into recipient from jsonb_array_elements(e.command#>'{payload,recipients}')x where x->>'profileId'=a::text and exists(select 1 from public.employees emp where emp.tenant_id=t and emp.profile_id=a and emp.id::text=x->>'id'and emp.status in('active','aktiv'));
 if recipient is null then continue;end if;
 select care_tour_planning_private.event_json(z)into ack from care_tour_planning_private.events z where z.tenant_id=t and z.plan_id=e.plan_id and z.kind='acknowledge'and z.actor_id=a and z.command#>>'{payload,publishEventId}'=e.id::text and z.command#>'{payload,recipient}'=recipient order by z.sequence desc limit 1;
 select r.head_id into head from care_tour_planning_private.roots r where r.tenant_id=t and r.plan_id=e.plan_id;
 -- The publication packet contains addressed plan content, never Q personnel histories.
 rows:=rows||jsonb_build_array(jsonb_build_object('publication',jsonb_build_object('id',e.id,'tenantId',e.tenant_id,'planId',e.plan_id,'sequence',e.sequence,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'version',e.command->>'version','versionLabel',e.command#>>'{payload,versionLabel}','validFrom',e.command#>>'{payload,validFrom}','validUntil',e.command#>>'{payload,validUntil}','packet',e.command#>'{payload,packet}'),'recipient',recipient,'headId',head,'current',care_tour_planning_private.publication_current(t,e.plan_id,e.id),'acknowledgement',ack));
 end loop;
 perform care_tour_planning_private.recipient_actor(t,a,false);
 return jsonb_build_object('version','2026-10-16.2','tenantId',t,'actorId',a,'count',jsonb_array_length(rows),'publications',rows);
end$$;
create or replace function care_tour_planning_private.commit_event(p_command jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare t uuid:=(p_command->>'tenantId')::uuid;p uuid:=(p_command->>'planId')::uuid;a uuid:=(p_command->>'actorId')::uuid;rid uuid:=(p_command->>'requestId')::uuid;eid uuid:=(p_command->>'eventId')::uuid;expected uuid:=(p_command->>'expectedHeadId')::uuid;
 root care_tour_planning_private.roots%rowtype;prior care_tour_planning_private.events%rowtype;actor_name text;seq bigint;personal boolean:=p_command->>'kind'='acknowledge';begin
 if p_command->>'version'is distinct from '2026-10-16.2'then raise exception using errcode='22023',message='Ältere Originalanfragen ausschließlich lesend bestätigen.';end if;
 actor_name:=case when personal then care_tour_planning_private.recipient_actor(t,a,true)else care_tour_planning_private.actor(t,a,true)end;
 -- Serialize the new private planning writers across tours before checking shared resources.
 perform pg_advisory_xact_lock(hashtextextended('tour-planning:'||t::text,0));
 -- Native writers must be covered by the separate compatibility gate. Hold originals/gaps
 -- stable within this transaction; verify lock order, duration and deadlocks on real PG.
 lock table public.care_tours,public.care_tour_stops,public.care_staff_shifts,public.employee_availability,public.employee_absences,public.employee_qualifications,public.employee_documents,public.employees,public.client_preferences,public.care_admissions,public.care_plans,public.care_plan_items,public.employee_logbook_vehicles,public.employee_logbook_trips,care_personnel_private.roots,care_personnel_private.events in share mode;
 actor_name:=case when personal then care_tour_planning_private.recipient_actor(t,a,true)else care_tour_planning_private.actor(t,a,true)end;
 if not personal then perform care_tour_planning_private.plan_access(t,p);end if;
 insert into care_tour_planning_private.roots(tenant_id,plan_id)values(t,p)on conflict do nothing;
 select*into root from care_tour_planning_private.roots where tenant_id=t and plan_id=p for update;
 select*into prior from care_tour_planning_private.events where tenant_id=t and request_id=rid;
 if found then if prior.command is distinct from p_command then raise exception using errcode='23505',message='Anfragekennung gehört zu einem anderen Original.';end if;return care_tour_planning_private.receipt(prior);end if;
 if root.head_id is distinct from expected then raise exception using errcode='40001',message='Planungskopf geändert; vollständigen Stand neu laden.';end if;
 perform care_tour_planning_private.history(t,p);perform care_tour_planning_private.validate_command(t,p,a,p_command);
 seq:=coalesce((select max(sequence)+1 from care_tour_planning_private.events where tenant_id=t and plan_id=p),1);
 insert into care_tour_planning_private.events(id,tenant_id,plan_id,sequence,previous_id,request_id,actor_id,actor_name,occurred_at,kind,command)values(eid,t,p,seq,expected,rid,a,actor_name,(p_command->>'occurredAt')::timestamptz,p_command->>'kind',p_command)returning*into prior;
 update care_tour_planning_private.roots set head_id=eid,updated_at=clock_timestamp()where tenant_id=t and plan_id=p;
 perform case when personal then care_tour_planning_private.recipient_actor(t,a,true)else care_tour_planning_private.actor(t,a,true)end;
 return care_tour_planning_private.receipt(prior);
end$$;
create or replace function care_tour_planning_private.confirm_event(p_tenant uuid,p_actor uuid,p_plan uuid,p_request uuid,p_command jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare e care_tour_planning_private.events%rowtype;personal boolean:=p_command->>'kind'='acknowledge';begin
 perform case when personal then care_tour_planning_private.recipient_actor(p_tenant,p_actor,false)else care_tour_planning_private.actor(p_tenant,p_actor,false)end;
 select*into e from care_tour_planning_private.events where tenant_id=p_tenant and plan_id=p_plan and request_id=p_request and actor_id=p_actor;
 if not found or e.command is distinct from p_command then raise exception using errcode='P0P01',message='Exakte Originalquittung noch nicht bestätigt.';end if;
 if personal and e.command#>>'{payload,recipient,profileId}'is distinct from p_actor::text then raise exception using errcode='42501',message='Eigener ursprünglicher Empfangsbezug fehlt.';end if;
 -- Old v1 commands are returned exactly; never replayed or rewritten as v2.
 perform case when personal then care_tour_planning_private.recipient_actor(p_tenant,p_actor,false)else care_tour_planning_private.actor(p_tenant,p_actor,false)end;
 return care_tour_planning_private.receipt(e);
end$$;
create or replace function public.web_tour_planning_plans(p_tenant_id uuid,p_actor_id uuid)returns jsonb language sql security invoker set search_path='' as $$select care_tour_planning_private.read_plans(p_tenant_id,p_actor_id)$$;
create or replace function public.web_tour_planning_context(p_tenant_id uuid,p_actor_id uuid,p_plan_id uuid)returns jsonb language sql security invoker set search_path='' as $$select care_tour_planning_private.read_context(p_tenant_id,p_actor_id,p_plan_id)$$;
create or replace function public.web_my_tour_publications(p_tenant_id uuid,p_actor_id uuid)returns jsonb language sql security invoker set search_path='' as $$select care_tour_planning_private.read_inbox(p_tenant_id,p_actor_id)$$;
create or replace function public.web_commit_tour_planning_event(p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select care_tour_planning_private.commit_event(p_command)$$;
create or replace function public.web_confirm_tour_planning_event(p_tenant_id uuid,p_actor_id uuid,p_plan_id uuid,p_request_id uuid,p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select care_tour_planning_private.confirm_event(p_tenant_id,p_actor_id,p_plan_id,p_request_id,p_command)$$;
-- Private schema stays outside exposed PostgREST schemas. Public wrappers are INVOKER:
-- grant only their guarded entry functions, never history/sources/helpers or raw tables.
revoke all on all functions in schema care_tour_planning_private from public,anon,authenticated;
grant usage on schema care_tour_planning_private to authenticated;
grant execute on function care_tour_planning_private.read_plans(uuid,uuid),care_tour_planning_private.read_context(uuid,uuid,uuid),care_tour_planning_private.read_inbox(uuid,uuid),care_tour_planning_private.commit_event(jsonb),care_tour_planning_private.confirm_event(uuid,uuid,uuid,uuid,jsonb)to authenticated;
revoke all on function public.web_tour_planning_plans(uuid,uuid),public.web_tour_planning_context(uuid,uuid,uuid),public.web_my_tour_publications(uuid,uuid),public.web_commit_tour_planning_event(jsonb),public.web_confirm_tour_planning_event(uuid,uuid,uuid,uuid,jsonb)from public,anon,authenticated;
grant execute on function public.web_tour_planning_plans(uuid,uuid),public.web_tour_planning_context(uuid,uuid,uuid),public.web_my_tour_publications(uuid,uuid),public.web_commit_tour_planning_event(jsonb),public.web_confirm_tour_planning_event(uuid,uuid,uuid,uuid,jsonb)to authenticated;
commit;
